-- Phase 5: distinguish Professional and Advanced mock-exam question banks.
alter table public.quiz_questions
  add column if not exists exam_track text not null default 'professional'
  check (exam_track in ('professional','advanced'));

create index if not exists quiz_questions_exam_track_idx
  on public.quiz_questions (exam_track, is_certification, difficulty);

-- Original practice questions written for this learning portal.
-- They are not official Saviynt exam questions or copied exam dumps.

create index if not exists quiz_questions_certification_track_idx
  on public.quiz_questions (is_certification, exam_track, difficulty);
